import type { LevelDef, LevelIndexItem } from './types';

// Levels live in public/levels as JSON (generated by scripts/gen-levels.mjs).
const BASE = '/levels';

export async function loadIndex(): Promise<LevelIndexItem[]> {
  const res = await fetch(`${BASE}/index.json`);
  if (!res.ok) throw new Error(`Could not load the level index (${res.status})`);
  const json = (await res.json()) as { levels: LevelIndexItem[] };
  return json.levels;
}

export async function loadLevel(item: LevelIndexItem): Promise<LevelDef> {
  const res = await fetch(`${BASE}/${item.file}`);
  if (!res.ok) throw new Error(`Could not load ${item.file} (${res.status})`);
  const def = (await res.json()) as LevelDef;
  validateLevel(def, item.file);
  return def;
}

// Minimal validation so malformed JSON fails with a clear message
export function validateLevel(def: LevelDef, source: string): void {
  const fail = (msg: string) => { throw new Error(`${source}: ${msg}`); };
  if (!def.world || !(def.world.width > 800)) fail('world.width must be greater than 800');
  if (!Array.isArray(def.birds) || def.birds.length === 0) fail('birds is empty');
  if (!Array.isArray(def.pigs) || def.pigs.length === 0) fail('pigs is empty');
  if (!Array.isArray(def.blocks)) fail('blocks must be a list');
}
